    async def start_dataset_checks(
        self,
        project_id: str,
        dataset_id: str,
        *,
        agent_slug: str,
        idempotency_key: str,
        dataset_version: typing.Optional[int] = OMIT,
        version: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> DatasetChecksStarted:
        """
        One Check per eligible example, each started as a production run of the agent's live version.

        Credits are admitted before anything is created. A retry of the same key
        returns the same checks and starts only what did not start before.

        Parameters
        ----------
        project_id : str

        dataset_id : str

        agent_slug : str

        idempotency_key : str

        dataset_version : typing.Optional[int]
            Omit for the latest dataset version.

        version : typing.Optional[str]
            The agent version to check; Checks run on the agent's live version.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        DatasetChecksStarted
            Successful Response

        Examples
        --------
        import asyncio

        from sikaru_api import AsyncSikaruApi

        client = AsyncSikaruApi(
            channel_credential="YOUR_CHANNEL_CREDENTIAL",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.datasets.start_dataset_checks(
                project_id="project_id",
                dataset_id="dataset_id",
                agent_slug="agent_slug",
                idempotency_key="idempotency_key",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.start_dataset_checks(
            project_id,
            dataset_id,
            agent_slug=agent_slug,
            idempotency_key=idempotency_key,
            dataset_version=dataset_version,
            version=version,
            request_options=request_options,
        )
        return _response.data

